param([string]$Root)

# Compares the transitive actions the lockfile pins against the THIRDPARTY inventory.
$lockPath = Join-Path $Root ".github\workflows\actions.lock"
if (-not (Test-Path $lockPath)) { Write-Output "NO LOCKFILE"; exit 1 }

$lines = Get-Content $lockPath
$section = ""
$direct = @{}
$deps = @()
foreach ($l in $lines) {
  if ($l -match '^(\w+):\s*$') { $section = $Matches[1]; continue }
  if ($l -match "^\s+- '([^']+)'") {
    $ref = $Matches[1]
    if ($section -eq 'dependencies') { $deps += $ref }
    elseif ($section -eq 'workflows') { $direct[$ref.Split('@')[0]] = $ref.Split('@')[1] }
  }
}

$inv = Join-Path $Root "THIRDPARTY.md"
$invText = if (Test-Path $inv) { [System.IO.File]::ReadAllText($inv) } else { "" }

Write-Output "=== $(Split-Path $Root -Leaf) ==="
foreach ($d in $deps) {
  $parts = $d.Split('@')
  $name = $parts[0]; $sha = $parts[1]
  $inInventory = $invText -match [regex]::Escape($name)
  $isDirect = $direct.ContainsKey($name)
  $tag = if ($isDirect) { "DIRECT-ALSO" } else { "TRANSITIVE-ONLY" }
  $mark = if ($inInventory) { "listed" } else { "MISSING-FROM-INVENTORY" }
  Write-Output ("  {0,-28} {1} {2,-16} {3}" -f $name, $sha.Substring(0,8), $tag, $mark)
}
