param([Parameter(Mandatory=$true)][string]$Root)

# Sweeps every tracked Markdown file for an Action version claim that disagrees
# with the live workflow pin. Section 6.E surface 5 covers README prose, not only
# the inventory, and a review caught a stale README line the inventory-only check
# missed. Historical CHANGELOG entries are dated fact and are excluded.
$ErrorActionPreference = 'Continue'
Push-Location $Root
try {
  $repo = Split-Path $Root -Leaf
  $pins = @{}
  foreach ($f in (Get-ChildItem ".github\workflows" -Filter "*.yml" -ErrorAction SilentlyContinue)) {
    foreach ($line in (Get-Content $f.FullName)) {
      if ($line -match 'uses:\s*([^\s@]+)@([0-9a-f]{40})\s*#\s*(v[0-9][0-9A-Za-z\.\-]*)') {
        $rootAction = ($Matches[1] -split '/')[0..1] -join '/'
        if (-not $pins.ContainsKey($rootAction)) { $pins[$rootAction] = @() }
        $pins[$rootAction] += $Matches[3]
      }
    }
  }
  # Lockfile refs are legitimate values for transitive paths.
  $lockRefs = @{}
  $sec = ""
  $curKey = ""
  if (Test-Path ".github\workflows\actions.lock") {
    foreach ($line in (Get-Content ".github\workflows\actions.lock")) {
      if ($line -match '^(\w+):\s*$') { $sec = $Matches[1]; continue }
      if ($sec -eq 'dependencies' -and $line -match "^    '([^']+@[0-9a-f]{40})':") { $curKey = ($Matches[1] -split '@')[0]; continue }
      if ($sec -eq 'dependencies' -and $curKey -and $line -match "^\s+ref:\s*'(v[^']+)'") {
        if (-not $lockRefs.ContainsKey($curKey)) { $lockRefs[$curKey] = @() }
        $lockRefs[$curKey] += $Matches[1]
      }
    }
  }

  $problems = @()
  $files = git ls-files '*.md' 2>$null | Where-Object { $_ -notmatch 'CHANGELOG' }
  foreach ($rel in $files) {
    $full = Join-Path $Root $rel
    if (-not (Test-Path $full)) { continue }
    $ln = 0
    foreach ($line in (Get-Content $full)) {
      $ln++
      # A row often names a parent Action and its child's version. Bind each
      # version to the nearest Action name to its LEFT, not to any name on the line.
      $names = @()
      foreach ($name in $pins.Keys) {
        foreach ($m in [regex]::Matches($line, [regex]::Escape($name))) {
          $names += @{ name = $name; pos = $m.Index }
        }
      }
      if ($names.Count -eq 0) { continue }
      foreach ($vm in [regex]::Matches($line, 'v[0-9]+\.[0-9]+\.[0-9]+')) {
        $v = $vm.Value
        # "the direct pin above is v7.0.2" refers back to the row's own subject,
        # not to the parent Action named just before it on the same line.
        $lead = $line.Substring(0, $vm.Index)
        # A transitive row contrasts its own version with the direct pin of the
        # same Action, naming the parent in between. Those phrasings refer back to
        # the row's subject, not to the parent named just before them.
        if ($lead -match "direct pin (above|below)?\s*(is|of)?\s*$") { continue }
        if ($lead -match '(from|than|distinto|diferente)\s+(the\s+)?(`?v[0-9.]+`?\s+)?direct\s*$') { continue }
        if ($line -match 'direct\s+v[0-9.]+\s+pin|`v[0-9.]+`\s+direct\s+pin') { continue }
        if ($lead -match 'direct\s+[A-Za-z-]*\s*pin\s+is\s+the\s+separate\s*$') { continue }
        $owner = $null; $best = -1
        foreach ($n in $names) {
          if ($n.pos -lt $vm.Index -and $n.pos -gt $best) { $best = $n.pos; $owner = $n.name }
        }
        if (-not $owner) { continue }
        $ok = ($pins[$owner] -contains $v)
        if (-not $ok -and $lockRefs.ContainsKey($owner)) { $ok = ($lockRefs[$owner] -contains $v) }
        if (-not $ok) {
          $problems += "$rel`:$ln $owner claims $v; workflow pins $(($pins[$owner] | Sort-Object -Unique) -join ',')"
        }
      }
    }
  }
  if ($problems.Count -eq 0) { Write-Output "$repo : VERSION-SWEEP CLEAN" }
  else { Write-Output "$repo : $($problems.Count)"; $problems | Sort-Object -Unique | ForEach-Object { "  $_" } }
} finally { Pop-Location }
