param([Parameter(Mandatory=$true)][string]$Root)

# Mechanical pre-push gate. Checks only claims about GitHub Actions, and only on
# lines this change actually added, so pre-existing npm SHAs and historical
# CHANGELOG entries do not drown the signal.
$ErrorActionPreference = 'Continue'
Push-Location $Root
try {
  $repo = Split-Path $Root -Leaf
  $problems = @()

  $pins = @{}
  foreach ($f in (Get-ChildItem ".github\workflows" -Filter "*.yml" -ErrorAction SilentlyContinue)) {
    foreach ($line in (Get-Content $f.FullName)) {
      if ($line -match 'uses:\s*([^\s@]+)@([0-9a-f]{40})\s*#\s*(v[0-9][0-9A-Za-z\.\-]*)') {
        $action = $Matches[1]; $sha = $Matches[2]; $ver = $Matches[3]
        $rootAction = ($action -split '/')[0..1] -join '/'
        foreach ($k in @($action, $rootAction)) {
          if (-not $pins.ContainsKey($k)) { $pins[$k] = @() }
          $pins[$k] += @{ sha = $sha; ver = $ver }
        }
      }
    }
  }
  $lockCommits = @()
  if (Test-Path ".github\workflows\actions.lock") {
    foreach ($line in (Get-Content ".github\workflows\actions.lock")) {
      if ($line -match "commit:\s*'sha1-([0-9a-f]{40})'") { $lockCommits += $Matches[1] }
    }
  }

  $added = @{}
  $diff = git diff -U0 origin/main...HEAD -- '*.md' 2>$null
  $cur = $null
  foreach ($l in $diff) {
    if ($l -match '^\+\+\+ b/(.+)$') { $cur = $Matches[1]; if (-not $added.ContainsKey($cur)) { $added[$cur] = @() } }
    elseif ($l -match '^\+' -and $l -notmatch '^\+\+\+' -and $cur) { $added[$cur] += $l.Substring(1) }
  }

  foreach ($f in $added.Keys) {
    if ($f -match 'CHANGELOG') { continue }
    # Paragraph context: a transitive-dependency explanation spans several lines.
    $allAdded = $added[$f] -join "`n"
    for ($li = 0; $li -lt $added[$f].Count; $li++) {
      $line = $added[$f][$li]
      $ctxStart = [Math]::Max(0, $li - 1)
      $ctxEnd = [Math]::Min($added[$f].Count - 1, $li + 2)
      $context = ($added[$f][$ctxStart..$ctxEnd] -join "`n")
      # A line describing a transitive dependency legitimately names a version no
      # workflow pins directly; the lockfile is its source of truth.
      $isTransitiveLine = $context -match 'transitive|transitiva'
      foreach ($m in [regex]::Matches($line, '([a-zA-Z0-9_\-]+/[a-zA-Z0-9_\-]+)(?:/[a-zA-Z0-9_\-]+)?`?\s+v([0-9]+\.[0-9]+\.[0-9]+)')) {
        $a = $m.Groups[1].Value; $v = "v" + $m.Groups[2].Value
        if ($pins.ContainsKey($a) -and -not $isTransitiveLine) {
          $vers = $pins[$a] | ForEach-Object { $_.ver } | Sort-Object -Unique
          if ($vers -notcontains $v) { $problems += "STALE-VERSION $f : $a stated $v, workflow pins $($vers -join ',')" }
        }
      }
      if ($line -match 'actions\.lock|uses:|claude-code-action|zizmor-action|codeql-action|linear-release-action|scorecard-action|dependency-review-action') {
        foreach ($m in [regex]::Matches($line, '[0-9a-f]{40}')) {
          $s = $m.Value
          $known = ($pins.Values | ForEach-Object { $_.sha }) -contains $s
          if (-not $known -and ($lockCommits -notcontains $s)) { $problems += "UNKNOWN-SHA $f : $s on an action/lockfile line" }
        }
      }
      if ($line -match 'gh actions-lock' -and $line -notmatch '--no-narrow' -and
          $line -notmatch 'CLI extension|default run|plain|rewrites|mutable tag|--verify|execu\S* simples|uma execu') {
        $problems += "BARE-GENERATOR $f : $($line.Trim().Substring(0,[Math]::Min(90,$line.Trim().Length)))"
      }
      # A section cross-reference needs its document named only when the file is
      # NOT the rule document itself. AGENTS.md/CLAUDE.md reference their own sections.
      if ($f -notmatch '(AGENTS|CLAUDE)\.md$' -and
          $line -match '(Se[cç][aã]o|Section)\s+[0-9]' -and
          $line -notmatch 'AGENTS\.md|CLAUDE\.md|this document|este documento') {
        $problems += "UNNAMED-DOC $f : $($line.Trim().Substring(0,[Math]::Min(90,$line.Trim().Length)))"
      }
    }
  }

  $editedInv = $added.Keys | Where-Object { $_ -match '(^|/)THIRDPARTY\.md$' }
  if ($editedInv -contains 'THIRDPARTY.md') {
    $h = (Get-FileHash 'THIRDPARTY.md').Hash
    # Only tracked copies count: build output under app/build or bin/ is regenerated
    # by the build and is not a published copy the change must keep in sync.
    $tracked = git ls-files '*THIRDPARTY.md' 2>$null
    foreach ($rel in $tracked) {
      if ($rel -eq 'THIRDPARTY.md') { continue }
      if ($rel -match 'node_modules|(^|/)dist/|admin-motor') { continue }
      $full = Join-Path $Root $rel
      if ((Test-Path $full) -and (Get-FileHash $full).Hash -ne $h) { $problems += "COPY-DRIFT $rel differs from THIRDPARTY.md" }
    }
  }

  if ((Test-Path 'AGENTS.md') -and (Test-Path 'CLAUDE.md')) {
    if ((Get-FileHash 'AGENTS.md').Hash -ne (Get-FileHash 'CLAUDE.md').Hash) { $problems += 'MIRROR AGENTS.md != CLAUDE.md' }
  }
  $wf = git diff --name-only origin/main...HEAD -- .github/workflows/ 2>$null | Where-Object { $_ -match '\.yml$' }
  if ($wf) { $problems += "WORKFLOW-CHANGED $($wf -join ',')" }
  if ((git merge-base origin/main HEAD 2>$null) -ne (git rev-parse origin/main 2>$null)) { $problems += 'STALE-BASE' }

  if ($problems.Count -eq 0) { Write-Output "$repo : CLEAN" }
  else { Write-Output "$repo : $($problems.Count)"; $problems | Sort-Object -Unique | ForEach-Object { "  $_" } }
} finally { Pop-Location }
