param([string]$Root)

# Reconciles THIRDPARTY version claims against the live workflow pins, and lists
# transitive-only actions the lockfile pins that have no inventory row.
$wfDir = Join-Path $Root ".github\workflows"
$pins = @{}
Get-ChildItem $wfDir -Filter "*.yml" | ForEach-Object {
  foreach ($l in (Get-Content $_.FullName)) {
    if ($l -match 'uses:\s*([^\s@]+)@([0-9a-f]{40})\s*#\s*(\S+)') {
      $pins[$Matches[1]] = @{ sha = $Matches[2]; ver = $Matches[3] }
    }
  }
}

$lock = Join-Path $wfDir "actions.lock"
$deps = @()
$sec = ""
foreach ($l in (Get-Content $lock)) {
  if ($l -match '^(\w+):\s*$') { $sec = $Matches[1]; continue }
  if ($l -match "^\s+- '([^']+)@([0-9a-f]{40})'" -and $sec -eq 'dependencies') {
    $deps += @{ name = $Matches[1]; sha = $Matches[2] }
  }
}

$invPath = Join-Path $Root "THIRDPARTY.md"
$inv = [System.IO.File]::ReadAllText($invPath)
$invLines = $inv -split "`n"

Write-Output "=== $(Split-Path $Root -Leaf) ==="
foreach ($name in ($pins.Keys | Sort-Object)) {
  $p = $pins[$name]
  $rows = @()
  for ($i = 0; $i -lt $invLines.Count; $i++) {
    if ($invLines[$i] -match [regex]::Escape($name)) { $rows += $i }
  }
  if ($rows.Count -eq 0) { Write-Output "  NO-ROW      $name $($p.ver)"; continue }
  $verOk = $false; $shaOk = $false
  foreach ($i in $rows) {
    if ($invLines[$i] -match [regex]::Escape($p.ver)) { $verOk = $true }
    if ($invLines[$i] -match [regex]::Escape($p.sha)) { $shaOk = $true }
  }
  if (-not $verOk) {
    $found = @()
    foreach ($i in $rows) { foreach ($m in [regex]::Matches($invLines[$i], 'v\d+\.\d+\.\d+')) { $found += $m.Value } }
    Write-Output ("  STALE-VER   {0,-40} pin={1} inventory={2}" -f $name, $p.ver, (($found | Sort-Object -Unique) -join ","))
  }
}
foreach ($d in $deps) {
  if (-not $pins.ContainsKey($d.name)) {
    if ($inv -notmatch [regex]::Escape($d.name)) { Write-Output "  MISSING-TRANSITIVE $($d.name) $($d.sha.Substring(0,8))" }
  }
}
